PREFIX brick: <https://brickschema.org/schema/Brick/>
PREFIX ref: <https://brickschema.org/schema/Brick/ref#>
SELECT DISTINCT ?z ?point ?ts WHERE {
  ?z rdfs:label "Perimeter_ZN_1" .
  ?p ref:isPointOf ?z .
  ?p a ?pc .
  OPTIONAL { ?p ref:hasExternalReference ?refp . ?refp ref:hasTimeseriesId ?ts . }
  BIND(STR(?p) AS ?point)
  BIND(STR(?pc) AS ?z)
}

